#include "common.h"
#include "actors/actor_800100.h"
#include "gameplay/3CD8.h"
#include "main/gfx.h"
#include "main/mem.h"
#include "m2c_macros.h"

extern u8 D_80073BA9;
extern u16 D_80112F60[];

void func_actor_800100_80166F50(GpActorWork* arg0)
{
    GameActor*     actor;
    GpObj*         obj;
    GpActorD4Rec*  rec;
    GsCOORDINATE2* src;
    Task*          task;

    actor = arg0->actor;
    task  = actor->field_91C;
    if (task != NULL) {
        obj   = (GpObj*)actor->field_12C;
        rec   = (GpActorD4Rec*)actor->pad_164;
        src   = (GsCOORDINATE2*)((TmdObject*)task->extra)->coords;
        *(GsCOORDINATE2*)actor->field_3D4 = *src;
        Gfx_RotMatrixX(&((GsCOORDINATE2*)actor->field_3D4)->workm, 0x400, 0);
        obj->coord  = actor->field_3D4;
        obj->ctx.recs  = (GpRec18*)actor->pad_164;
        obj->key = 0x60000;
        obj->flags    = 3;
        obj->pos.vx = 0;
        obj->pos.vy = 0;
        obj->pos.vz = 0;
        rec->end1.vx  = 0;
        rec->end1.vy  = -0x10;
        rec->end0.vx  = rec->end1.vx;
        rec->end1.vz  = 0x20;
        rec->end0.vy  = rec->end1.vy;
        rec->end0.vz  = rec->end1.vz + D_80112F60[D_80073BA9];
        rec->end1Radius = 1;
        rec->end0Radius = 1;
        rec->recs = (GpRec18*)actor->pad_3BC;
        Gp_LinkObj(1, obj);
        Gp_InitRec18Table(rec->recs, 1, 0);
        obj->flags |= 0x800;
    }
}

